{
  "title": "Slow morning, sea breeze afternoon",
  "summary": "A lazy start, a beach wander, a proper bowl of noodles, then a gentle evening by the water.",
  "stops": [
    {
      "poi_id": "p36",
      "kind": "activity",
      "must_do_id": null,
      "note": "With a slow morning, East Sea Park is the right first breath: easy walking, sea air, no rush.",
      "note": "With a slow morning, East Sea Park is the right first breath: easy walking, sea air, no rush."
    },
    {
      "poi_id": "p50",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch is mì Quảng (turmeric noodles with pork, shrimp and a sesame cracker) at Mì Quảng Nhung, because a slow day still needs a proper bowl."
    },
    {
      "poi_id": "p82",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bãi Biển Phạm Văn Đồng is the sunset spot, quiet and close, so the day ends where the sky does the work."
    },
    {
      "poi_id": "p53",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner is Ốc Cười, street food and local life in one, because one person at a snail table is never lonely."
    }
  ]
}
